head.script:
scwin.btn_trigger1_onclick = async function() {
    var tempMenuCd = "cmcm001" + scwin.n++
    await tabControl1.addTab(tempMenuCd, {
        "label": "공통코드등록",
        "title": "공통코드등록",
        "openAction": "new",
        "closable": "true"
    }, {
        "src": "wframe_dynamicCreate_WPFF-276_(WSQ-3644)_tab3.xml",
        "wframe": true,
        "scope": true,
        "alwaysDraw": false
    });
    await tabControl1.setSelectedTabIndex(tempMenuCd);
    var wfmObj = tabControl1.getFrame(tabControl1.getTabIndex(tempMenuCd));
    var targetObj = WebSquare.util.getChildren(wfmObj, {
        recursive: true
    })[0] || "";
    var screenObj = wfmObj.getObj("$p").dynamicCreate("wfmScreenHeader", "wframe", {
        mode: "sync",
        scope: true
    }, targetObj);
    if (await screenObj.setSrc("wframe_dynamicCreate_WPFF-276_(WSQ-3644)_tab2.xml")) {
        screenObj.getObj("scwin").init();
    }
};
scwin.btn_trigger2_onclick = function() {
    tabControl1.getFrame(1).setSrc("wframe_dynamicCreate_WPFF-276_(WSQ-3644)_tab2.xml");
};
scwin.btn_trigger3_onclick = function() {
    tabControl1.getFrame(1).setSrc("wframe_dynamicCreate_WPFF-276_(WSQ-3644)_tab1.xml");
};
scwin.btn_trigger4_onclick = function() {
    tabControl1.setSelectedTabIndex(1);
    var wfmObj = tabControl1.getFrame(1);
    var targetObj = WebSquare.util.getChildren(wfmObj, {
        "recursive": true
    })[0] || "";
    console.log(targetObj.render);
    var screenObj = scwin.$p.dynamicCreate("wfmScreenHeader", "wframe", {
        "mode": "sync",
        "scope": true
    }, targetObj);
    console.log(screenObj.render);
    if (screenObj.setSrc("wframe_dynamicCreate_WPFF-276_(WSQ-3644)_tab1.xml")) {
        screenObj.getObj("scwin").init();
    }
};
scwin.onpageload = function() {
    scwin.n = 0;
}
